import type { Metadata } from "next";
import Link from "next/link";
import { redirect } from "next/navigation";
import { getCurrentUserProfile } from "@/src/lib/auth";
import { getManagedCompanies } from "@/src/lib/vendor";

export const dynamic = "force-dynamic";
export const metadata: Metadata = { title: "Vendor Dashboard", robots: { index: false, follow: false } };
export default async function VendorDashboard() { const user = await getCurrentUserProfile(); if (!user) redirect("/sign-in?redirect_url=%2Fvendor"); const memberships = await getManagedCompanies(user.id); return <main className="mx-auto min-h-[70vh] max-w-5xl px-4 py-12"><div className="flex flex-wrap items-end justify-between gap-4"><div><p className="overline">Vendor</p><h1 className="mt-2 text-h1 text-text-primary">Vendor Dashboard</h1><p className="mt-3 text-body text-text-secondary">Manage verified company information and respond to product enquiries.</p></div>{memberships.length > 0 && <Link href="/vendor/leads" className="rounded-md bg-text-primary px-4 py-2 text-caption font-semibold text-bg">View leads</Link>}</div>{memberships.length ? <div className="mt-8 grid gap-5 md:grid-cols-2">{memberships.map(({ company }) => <article key={company.id} className="card-surface p-6"><div className="flex items-center justify-between gap-3"><h2 className="text-h2 text-text-primary">{company.name}</h2><span className="rounded border border-border px-2 py-1 text-caption text-text-secondary">Verified identity</span></div><p className="mt-2 text-body text-text-secondary">{company.shortDescription ?? "Company profile"}</p><p className="mt-4 text-caption text-text-tertiary">{company.products.length} products · {company._count.leads} leads</p><div className="mt-5 flex flex-wrap gap-3"><Link href={`/vendor/companies/${company.slug}`} className="text-caption font-semibold text-accent">Edit company</Link>{company.products.map((product) => <Link key={product.id} href={`/vendor/products/${product.slug}`} className="text-caption font-semibold text-accent">Edit {product.name}</Link>)}</div></article>)}</div> : <div className="mt-8 rounded-lg border border-dashed border-border p-8"><h2 className="text-h3 text-text-primary">No claimed companies</h2><p className="mt-2 text-body text-text-secondary">Find your company profile and submit a claim for administrator review.</p><Link href="/companies" className="mt-4 inline-block text-caption font-semibold text-accent">Find your company →</Link></div>}</main>; }
